import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test("A file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("DOC-05 Vendor"),
      category: "software",
      contact_email: "billing@example.com",
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = (await vendorRes.json()) as { id: string };

  // Act
  const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "contract",
      file: {
        name: "contract-10mib.txt",
        mimeType: "text/plain",
        buffer: Buffer.alloc(TEN_MIB, "x"),
      },
    },
  });

  // Assert
  expect(res.status(), await res.text()).toBe(201);
});
